    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> vOutQueue_;

    // Buffers
    AscendC::TBuf<AscendC::TPosition::VECCALC> rmsInBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> ropeInBuf_;
    AscendC::TBuf<AscendC::TPosition::VECCALC> rmsSqBuf_;
