11	// AscendC kernel for fused KV RMSNorm + RoPE + Cache
12	// Supports float16, bfloat16
13	// Processes one (batch, seq, head) element at a time
14	
15	#include "kernel_operator.h"
16	
17	constexpr int32_t BUFFER_NUM = 2;
18	
19	// Tiling data structure
20	struct KvRmsnormRopeCacheTiling {
