41	
42	__aicore__ inline uint32_t CeilDivU32(uint32_t a, uint32_t b) {
43	    if (b == 0U) { return 0U; }
44	    return (a + b - 1U) / b;
45	}
46	
47	template <typename T>
48	__aicore__ inline void LoadGmToUb(
49	    AscendC::LocalTensor<T> &dst,
50	    AscendC::GlobalTensor<T> src,
51	    uint32_t count)
52	{
53	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
54	    AscendC::DataCopyPadExtParams<T> padParams{true, 0, 0, static_cast<T>(0)};
55	    AscendC::DataCopyPad(dst, src, copyParams, padParams);
56	}
57	
58	template <typename T>
59	__aicore__ inline void StoreUbToGm(
60	    AscendC::GlobalTensor<T> dst,
61	    AscendC::LocalTensor<T> &src,
62	    uint32_t count)
63	{
64	    AscendC::DataCopyExtParams copyParams{1, count * static_cast<uint32_t>(sizeof(T)), 0, 0, 0};
65	    AscendC::DataCopyPad(dst, src, copyParams);
66	}
67	
68	template <typename T>
69	__aicore__ inline AscendC::RoundMode OutputRoundModeHelper() {
70	    if constexpr (std::is_same_v<T, bfloat16_t>) {
71	        return AscendC::RoundMode::CAST_ROUND;
72	    }
73	    return AscendC::RoundMode::CAST_NONE;
74	}
