// AscendC kernel for fused KV RMSNorm + RoPE + Cache
// Supports float16, bfloat16
// Processes one (batch, seq, head) element at a time

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

// =========================================================================
// Main Kernel Class
// =========================================================================

template <typename dataType>
class KvRmsnormRopeCacheKernel {
public:
    __aicore__ inline void Init(
        GM_ADDR kv, GM_ADDR gamma, GM_ADDR cos, GM_ADDR sin,
        GM_ADDR index, GM_ADDR k_cache, GM_ADDR ckv_cache,
        GM_ADDR k_rope_scale, GM_ADDR c_kv_scale,
        GM_ADDR k_rope_offset, GM_ADDR c_kv_offset,
        GM_ADDR k_cache_out, GM_ADDR ckv_cache_out,
        GM_ADDR k_embed_out, GM_ADDR v_out,
        int32_t B, int32_t S, int32_t N,
        int32_t hidden_size, int32_t rms_size, int32_t rope_size,
        int32_t cache_mode, int32_t is_output_kv,
        int32_t has_quant_k, int32_t has_quant_v,
        float epsilon, int32_t total_elements,
        int32_t usedCoreNum, int32_t tasksPerCore,
        int64_t dtypeFlag)
    {
        B_ = B;
        S_ = S;
        N_ = N;
        hidden_size_ = hidden_size;
        rms_size_ = rms_size;
        rope_size_ = rope_size;
        cache_mode_ = cache_mode;
        is_output_kv_ = is_output_kv;
        has_quant_k_ = has_quant_k;
        has_quant_v_ = has_quant_v;
        epsilon_ = epsilon;
        total_elements_ = total_elements;
        tasksPerCore_ = tasksPerCore;

        kvGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(kv),
                              static_cast<uint64_t>(B) * N * S * hidden_size);
        gammaGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(gamma), rms_size);
        cosGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(cos),
                               static_cast<uint64_t>(B) * N * S * rope_size);
        sinGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(sin),
                               static_cast<uint64_t>(B) * N * S * rope_size);
        indexGM_.SetGlobalBuffer(reinterpret_cast<__gm__ int64_t *>(index), B * S);
        k_cache_outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(k_cache_out),
                                       static_cast<uint64_t>(B) * N * S * 4 * rope_size);
        ckv_cache_outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(ckv_cache_out),
                                         static_cast<uint64_t>(B) * N * S * 4 * rms_size);

        if (is_output_kv) {
            k_embed_outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(k_embed_out),
                                           static_cast<uint64_t>(B) * N * S * rope_size);
            v_outGM_.SetGlobalBuffer(reinterpret_cast<__gm__ dataType *>(v_out),
                                     static_cast<uint64_t>(B) * N * S * rms_size);
        }

        if ASCEND_IS_AIV {
            // Input queues
            pipe.InitBuffer(kvInQueue_, BUFFER_NUM, (rms_size + rope_size) * sizeof(dataType));
            pipe.InitBuffer(gammaInQueue_, BUFFER_NUM, rms_size * sizeof(dataType));
            pipe.InitBuffer(cosInQueue_, BUFFER_NUM, rope_size * sizeof(dataType));
            pipe.InitBuffer(sinInQueue_, BUFFER_NUM, rope_size * sizeof(dataType));

            // Output queues
            pipe.InitBuffer(kCacheOutQueue_, BUFFER_NUM, rope_size * sizeof(dataType));
            pipe.InitBuffer(ckvCacheOutQueue_, BUFFER_NUM, rms_size * sizeof(dataType));

            if (is_output_kv) {
                pipe.InitBuffer(kEmbedOutQueue_, BUFFER_NUM, rope_size * sizeof(dataType));
                pipe.InitBuffer(vOutQueue_, BUFFER_NUM, rms_size * sizeof(dataType));
            }

            // Intermediate FP32 buffers
            pipe.InitBuffer(rmsInBuf_, rms_size * sizeof(float));
            pipe.InitBuffer(ropeInBuf_, rope_size * sizeof(float));
            pipe.InitBuffer(rmsSqBuf_, rms_size * sizeof(float));
            pipe.InitBuffer(rmsMeanBuf_, 16 * sizeof(float));
            pipe.InitBuffer(rmsNormBuf_, rms_size * sizeof(float));
            pipe.InitBuffer(vBuf_, rms_size * sizeof(float));

            pipe.InitBuffer(kBuf_, rope_size * sizeof(float));
            pipe.InitBuffer(k1Buf_, (rope_size / 2) * sizeof(float));
            pipe.InitBuffer(k2Buf_, (rope_size / 2) * sizeof(float));
            pipe.InitBuffer(rotateHalfBuf_, rope_size * sizeof(float));
            pipe.InitBuffer(kEmbedBuf_, rope_size * sizeof(float));
            pipe.InitBuffer(cosBuf_, rope_size * sizeof(float));
            pipe.InitBuffer(sinBuf_, rope_size * sizeof(float));

            // Cast buffers for FP16/BF16
            if constexpr (!std::is_same_v<dataType, float>) {
                pipe.InitBuffer(kvCastBuf_, (rms_size + rope_size) * sizeof(float));
                pipe.InitBuffer(gammaCastBuf_, rms_size * sizeof(float));
                pipe.InitBuffer(cosCastBuf_, rope_size * sizeof(float));
                pipe.InitBuffer(sinCastBuf_, rope_size * sizeof(float));
                pipe.InitBuffer(kCacheCastBuf_, rope_size * sizeof(float));
                pipe.InitBuffer(ckvCacheCastBuf_, rms_size * sizeof(float));
                if (is_output_kv) {
                    pipe.InitBuffer(kEmbedCastBuf_, rope_size * sizeof(float));
                    pipe.InitBuffer(vCastBuf_, rms_size * sizeof(float));
                }
            }

            // Reduce tmp buffer (float type for ReduceSum)
            pipe.InitBuffer(reduceTmpBuf_, rms_size * sizeof(float));
        }
    }

    __aicore__ inline void Process() {
        if ASCEND_IS_AIV {
            const int coreIdx = AscendC::GetBlockIdx() / AscendC::GetSubBlockNum();

            for (int localIdx = 0; localIdx < tasksPerCore_; ++localIdx) {
                const int elem_idx = coreIdx * tasksPerCore_ + localIdx;
                if (elem_idx >= total_elements_) {
                    continue;
                }

                const int b = elem_idx / (S_ * N_);
                const int s = (elem_idx / N_) % S_;
                const int n = elem_idx % N_;

                ProcessElement(b, s, n);
            }
        }
    }

private:
    __aicore__ inline void ProcessElement(int b, int s, int n) {
        int32_t rms_size = rms_size_;
        int32_t rope_size = rope_size_;
        int32_t hidden_size = hidden_size_;
        int32_t B = B_;
        int32_t S = S_;
        int32_t N = N_;

        // === 1. Load kv[b, n, s, :] ===
        auto kvIn = kvInQueue_.AllocTensor<dataType>();
        uint64_t kvOffset = static_cast<uint64_t>(b) * N * S * hidden_size
                          + static_cast<uint64_t>(n) * S * hidden_size
                          + static_cast<uint64_t>(s) * hidden_size;
        AscendC::DataCopyPad(kvIn, kvGM_[kvOffset],
            AscendC::DataCopyExtParams{1, static_cast<uint32_t>(hidden_size * sizeof(dataType)), 0, 0, 0},
            AscendC::DataCopyPadExtParams<dataType>{true, 0, 0, static_cast<dataType>(0)});
        kvInQueue_.EnQue(kvIn);

        // === 2. Load gamma, cos, sin ===
        auto gammaIn = gammaInQueue_.AllocTensor<dataType>();
        AscendC::DataCopyPad(gammaIn, gammaGM_,
            AscendC::DataCopyExtParams{1, static_cast<uint32_t>(rms_size * sizeof(dataType)), 0, 0, 0},
            AscendC::DataCopyPadExtParams<dataType>{true, 0, 0, static_cast<dataType>(0)});
        gammaInQueue_.EnQue(gammaIn);

        auto cosIn = cosInQueue_.AllocTensor<dataType>();
        auto sinIn = sinInQueue_.AllocTensor<dataType>();
        uint64_t cosSinOffset = static_cast<uint64_t>(b) * N * S * rope_size
                                + static_cast<uint64_t>(n) * S * rope_size
                                + static_cast<uint64_t>(s) * rope_size;
        AscendC::DataCopyPad(cosIn, cosGM_[cosSinOffset],
            AscendC::DataCopyExtParams{1, static_cast<uint32_t>(rope_size * sizeof(dataType)), 0, 0, 0},
            AscendC::DataCopyPadExtParams<dataType>{true, 0, 0, static_cast<dataType>(0)});
        AscendC::DataCopyPad(sinIn, sinGM_[cosSinOffset],
            AscendC::DataCopyExtParams{1, static_cast<uint32_t>(rope_size * sizeof(dataType)), 0, 0, 0},
            AscendC::DataCopyPadExtParams<dataType>{true, 0, 0, static_cast<dataType>(0)});
        cosInQueue_.EnQue(cosIn);
        sinInQueue_.EnQue(sinIn);

        // === 3. Dequeue inputs ===
        kvIn = kvInQueue_.DeQue<dataType>();
        gammaIn = gammaInQueue_.DeQue<dataType>();
        cosIn = cosInQueue_.DeQue<dataType>();
        sinIn = sinInQueue_.DeQue<dataType>();

        // Cast to FP32 for computation
        auto rmsInFp32 = rmsInBuf_.Get<float>();
        auto ropeInFp32 = ropeInBuf_.Get<float>();
        auto gammaFp32 = gammaCastBuf_.Get<float>();
        auto cosFp32 = cosBuf_.Get<float>();
        auto sinFp32 = sinBuf_.Get<float>();

        if constexpr (std::is_same_v<dataType, float>) {
            // For float32, reinterpret and copy
            auto kvFp32 = kvIn.template ReinterpretCast<float>();
            AscendC::DataCopy(rmsInFp32, kvFp32, rms_size);
            AscendC::DataCopy(ropeInFp32, kvFp32[rms_size], rope_size);
            AscendC::DataCopy(gammaFp32, gammaIn.template ReinterpretCast<float>(), rms_size);
            AscendC::DataCopy(cosFp32, cosIn.template ReinterpretCast<float>(), rope_size);
            AscendC::DataCopy(sinFp32, sinIn.template ReinterpretCast<float>(), rope_size);
        } else {
            auto kvFp32 = kvCastBuf_.Get<float>();
            AscendC::Cast(kvFp32, kvIn, AscendC::RoundMode::CAST_NONE, hidden_size);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopy(rmsInFp32, kvFp32, rms_size);
            AscendC::DataCopy(ropeInFp32, kvFp32[rms_size], rope_size);

            auto gammaFp32Tmp = gammaCastBuf_.Get<float>();
            AscendC::Cast(gammaFp32Tmp, gammaIn, AscendC::RoundMode::CAST_NONE, rms_size);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopy(gammaFp32, gammaFp32Tmp, rms_size);

            auto cosFp32Tmp = cosCastBuf_.Get<float>();
            auto sinFp32Tmp = sinCastBuf_.Get<float>();
            AscendC::Cast(cosFp32Tmp, cosIn, AscendC::RoundMode::CAST_NONE, rope_size);
            AscendC::Cast(sinFp32Tmp, sinIn, AscendC::RoundMode::CAST_NONE, rope_size);
            AscendC::PipeBarrier<PIPE_V>();
            AscendC::DataCopy(cosFp32, cosFp32Tmp, rope_size);
            AscendC::DataCopy(sinFp32, sinFp32Tmp, rope_size);
        }
        AscendC::PipeBarrier<PIPE_V>();

        // === 4. RMSNorm ===
        auto rmsSq = rmsSqBuf_.Get<float>();
        AscendC::Mul(rmsSq, rmsInFp32, rmsInFp32, rms_size);

        auto rmsMean = rmsMeanBuf_.Get<float>();
        auto reduceTmp = reduceTmpBuf_.Get<float>();
        AscendC::ReduceSum<float>(rmsMean, rmsSq, reduceTmp, rms_size);

        float meanVal = rmsMean.GetValue(0);
        meanVal = meanVal / static_cast<float>(rms_size) + epsilon_;
        AscendC::Duplicate(rmsMean, meanVal, 1);
        AscendC::Rsqrt(rmsMean, rmsMean, 1);
        AscendC::PipeBarrier<PIPE_V>();
        float invRms = rmsMean.GetValue(0);

        auto rmsNorm = rmsNormBuf_.Get<float>();
        AscendC::Muls(rmsNorm, rmsInFp32, invRms, rms_size);

        auto vFp32 = vBuf_.Get<float>();
        AscendC::Mul(vFp32, gammaFp32, rmsNorm, rms_size);

        // === 5. RoPE ===
        auto kFp32 = kBuf_.Get<float>();
        AscendC::DataCopy(kFp32, ropeInFp32, rope_size);

        int32_t half = rope_size / 2;
        auto k1 = k1Buf_.Get<float>();
        auto k2 = k2Buf_.Get<float>();
        auto rotateHalf = rotateHalfBuf_.Get<float>();

        AscendC::DataCopy(k1, kFp32, half);
        AscendC::DataCopy(k2, kFp32[half], half);
        AscendC::PipeBarrier<PIPE_V>();

        AscendC::Muls(rotateHalf, k2, -1.0f, half);
        AscendC::DataCopy(rotateHalf[half], k1, half);
        AscendC::PipeBarrier<PIPE_V>();

        auto kEmbed = kEmbedBuf_.Get<float>();
        AscendC::Mul(kEmbed, kFp32, cosFp32, rope_size);
        auto tmpMul = k1Buf_.Get<float>();
        AscendC::Mul(tmpMul, rotateHalf, sinFp32, rope_size);
        AscendC::Add(kEmbed, kEmbed, tmpMul, rope_size);

        // === 6. Prepare outputs ===
        auto kCacheOut = kCacheOutQueue_.AllocTensor<dataType>();
        auto ckvCacheOut = ckvCacheOutQueue_.AllocTensor<dataType>();

        if constexpr (std::is_same_v<dataType, float>) {
            AscendC::DataCopy(kCacheOut.template ReinterpretCast<float>(), kEmbed, rope_size);
            AscendC::DataCopy(ckvCacheOut.template ReinterpretCast<float>(), vFp32, rms_size);
        } else {
            auto kCacheFp32 = kCacheCastBuf_.Get<float>();
            auto ckvCacheFp32 = ckvCacheCastBuf_.Get<float>();
            AscendC::DataCopy(kCacheFp32, kEmbed, rope_size);
            AscendC::DataCopy(ckvCacheFp32, vFp32, rms_size);
            AscendC::Cast(kCacheOut, kCacheFp32, AscendC::RoundMode::CAST_ROUND, rope_size);
            AscendC::Cast(ckvCacheOut, ckvCacheFp32, AscendC::RoundMode::CAST_ROUND, rms_size);
            AscendC::PipeBarrier<PIPE_V>();
        }

        // === 7. Cache Write ===
        int64_t idx = indexGM_.GetValue(b * S + s);

        if (idx >= 0) {
            uint64_t kCacheOffset = static_cast<uint64_t>(b) * N * S * 4 * rope_size
                                    + static_cast<uint64_t>(n) * S * 4 * rope_size
                                    + static_cast<uint64_t>(idx) * rope_size;
            uint64_t ckvCacheOffset = static_cast<uint64_t>(b) * N * S * 4 * rms_size
                                      + static_cast<uint64_t>(n) * S * 4 * rms_size
                                      + static_cast<uint64_t>(idx) * rms_size;
            AscendC::DataCopyPad(k_cache_outGM_[kCacheOffset], kCacheOut,
                AscendC::DataCopyExtParams{1, static_cast<uint32_t>(rope_size * sizeof(dataType)), 0, 0, 0});
            AscendC::DataCopyPad(ckv_cache_outGM_[ckvCacheOffset], ckvCacheOut,
                AscendC::DataCopyExtParams{1, static_cast<uint32_t>(rms_size * sizeof(dataType)), 0, 0, 0});
        }

        kCacheOutQueue_.EnQue(kCacheOut);
        ckvCacheOutQueue_.EnQue(ckvCacheOut);

        // Free inputs
        kvInQueue_.FreeTensor(kvIn);
        gammaInQueue_.FreeTensor(gammaIn);
        cosInQueue_.FreeTensor(cosIn);
        sinInQueue_.FreeTensor(sinIn);

        // Dequeue and free outputs
        kCacheOut = kCacheOutQueue_.DeQue<dataType>();
        ckvCacheOut = ckvCacheOutQueue_.DeQue<dataType>();
        kCacheOutQueue_.FreeTensor(kCacheOut);
        ckvCacheOutQueue_.FreeTensor(ckvCacheOut);

        // === 8. Output kv if needed ===
        if (is_output_kv_) {
            auto kEmbedOut = kEmbedOutQueue_.AllocTensor<dataType>();
            auto vOut = vOutQueue_.AllocTensor<dataType>();

            if constexpr (std::is_same_v<dataType, float>) {
                AscendC::DataCopy(kEmbedOut.template ReinterpretCast<float>(), kEmbed, rope_size);
                AscendC::DataCopy(vOut.template ReinterpretCast<float>(), vFp32, rms_size);
            } else {
                auto kEmbedFp32 = kEmbedCastBuf_.Get<float>();
                auto vFp32Out = vCastBuf_.Get<float>();
                AscendC::DataCopy(kEmbedFp32, kEmbed, rope_size);
                AscendC::DataCopy(vFp32Out, vFp32, rms_size);
                AscendC::Cast(kEmbedOut, kEmbedFp32, AscendC::RoundMode::CAST_ROUND, rope_size);
                AscendC::Cast(vOut, vFp32Out, AscendC::RoundMode::CAST_ROUND, rms_size);
                AscendC::PipeBarrier<PIPE_V>();
            }

            uint64_t kEmbedOutOffset = static_cast<uint64_t>(b) * N * S * rope_size
                                       + static_cast<uint64_t>(n) * S * rope_size
                                       + static_cast<uint64_t>(s) * rope_size;
            uint64_t vOutOffset = static_cast<uint64_t>(b) * N * S * rms_size
                                  + static_cast<uint64_t>(n) * S * rms_size
                                  + static_cast<uint64_t>(s) * rms_size;
            AscendC::DataCopyPad(k_embed_outGM_[kEmbedOutOffset], kEmbedOut,
                AscendC::DataCopyExtParams{1, static_cast<uint32_t>(rope_size * sizeof(dataType)), 0, 0, 0});
            AscendC::DataCopyPad(v_outGM_[vOutOffset], vOut,
                AscendC::DataCopyExtParams{1, static_cast<uint32_t>(rms_size * sizeof(dataType)), 0, 0, 0});

            kEmbedOutQueue_.EnQue(kEmbedOut);
            vOutQueue_.EnQue(vOut);

            kEmbedOut = kEmbedOutQueue_.DeQue<dataType>();
            vOut = vOutQueue_.DeQue<dataType>();
            kEmbedOutQueue_.FreeTensor(kEmbedOut);
            vOutQueue_.FreeTensor(vOut);
        }
    }

private:
    // Tiling params
    int32_t B_ = 0;
    int32_t S_ = 0;
    int32_t N_ = 0;
    int32_t hidden_size_ = 0;
    int32_t rms_size_ = 0;
    int32_t rope_size_ = 0;
    int32_t cache_mode_ = 0;
    int32_t is_output_kv_ = 0;
    int32_t has_quant_k_ = 0;
    int32_t has_quant_v_ = 0;
    float epsilon_ = 0.0f;
    int32_t total_elements_ = 0;
    int32_t tasksPerCore_ = 0;

    AscendC::TPipe pipe;

    // GM tensors
    AscendC::GlobalTensor<dataType> kvGM_;
    AscendC::GlobalTensor<dataType> gammaGM_;
    AscendC::GlobalTensor<dataType> cosGM_;
    AscendC::GlobalTensor<dataType> sinGM_;
    AscendC::GlobalTensor<int64_t> indexGM_;
    AscendC::GlobalTensor<dataType> k_cache_outGM_;
    AscendC::GlobalTensor<dataType> ckv_cache_outGM_;
    AscendC::GlobalTensor<dataType> k_embed_outGM_;
    AscendC::GlobalTensor<dataType> v_outGM_;

    // Queues
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> kvInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> gammaInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> cosInQueue_;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> sinInQueue_;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> kCacheOutQueue_;
