// KV RMSNorm RoPE Cache op_host — tiling calculation + EXEC_KERNEL_CMD launch

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"

#include "aclrtlaunch_kv_rmsnorm_rope_cache.h"

constexpr int32_t DEFAULT_NUM_PHYSICAL_CORES = 20;

namespace ascend_kernel {

std::vector<at::Tensor> kv_rmsnorm_rope_cache(
    const at::Tensor &kv,
    const at::Tensor &gamma,
    const at::Tensor &cos,
    const at::Tensor &sin,
    const at::Tensor &index,
    const at::Tensor &k_cache,
    const at::Tensor &ckv_cache,
    const at::Tensor &k_rope_scale,
    const at::Tensor &c_kv_scale,
    const at::Tensor &k_rope_offset,
    const at::Tensor &c_kv_offset,
    double epsilon,
    const std::string &cache_mode,
    bool is_output_kv)
{
    // Input validation
    TORCH_CHECK(kv.dim() == 4, "kv must be 4D [B, N, S, hidden_size]");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [rms_size]");
    TORCH_CHECK(cos.dim() == 4, "cos must be 4D [B, N, S, rope_size]");
    TORCH_CHECK(sin.dim() == 4, "sin must be 4D [B, N, S, rope_size]");
    TORCH_CHECK(index.dim() == 1 || index.dim() == 2, "index must be 1D or 2D");
    TORCH_CHECK(k_cache.dim() == 4, "k_cache must be 4D");
    TORCH_CHECK(ckv_cache.dim() == 4, "ckv_cache must be 4D");
    TORCH_CHECK(kv.is_contiguous(), "kv must be contiguous");

    int32_t B = static_cast<int32_t>(kv.sizes()[0]);
    int32_t N = static_cast<int32_t>(kv.sizes()[1]);
    int32_t S = static_cast<int32_t>(kv.sizes()[2]);
    int32_t hidden_size = static_cast<int32_t>(kv.sizes()[3]);
    int32_t rms_size = static_cast<int32_t>(gamma.sizes()[0]);
    int32_t rope_size = hidden_size - rms_size;

    // Map cache_mode string to int
    int32_t cache_mode_int = 0;
    if (cache_mode == "Norm") cache_mode_int = 0;
    else if (cache_mode == "PA") cache_mode_int = 1;
    else if (cache_mode == "PA_BNSD") cache_mode_int = 2;
    else if (cache_mode == "PA_NZ") cache_mode_int = 3;
    else if (cache_mode == "PA_BLK_BNSD") cache_mode_int = 4;
    else if (cache_mode == "PA_BLK_NZ") cache_mode_int = 5;

    // Check quantization params
    int32_t has_quant_k = k_rope_scale.defined() && k_rope_scale.numel() > 0 ? 1 : 0;
    int32_t has_quant_v = c_kv_scale.defined() && c_kv_scale.numel() > 0 ? 1 : 0;

    // dtype flag: 0=fp32, 1=fp16, 2=bf16
    int64_t dtypeFlag = 0;
    if (kv.scalar_type() == at::kHalf) {
        dtypeFlag = 1;
    } else if (kv.scalar_type() == at::kBFloat16) {
        dtypeFlag = 2;
    }

    // Tiling calculation
    int32_t total_elements = B * S * N;
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int32_t num_physical_cores = static_cast<int32_t>(ascendc_platform->GetCoreNumAiv());
    int32_t usedCoreNum = std::min(num_physical_cores, std::max(1, total_elements));
    int32_t tasksPerCore = (total_elements + usedCoreNum - 1) / usedCoreNum;

    // Create output tensors
    at::Tensor k_cache_out = at::empty_like(k_cache);
    at::Tensor ckv_cache_out = at::empty_like(ckv_cache);
    at::Tensor k_embed_out;
    at::Tensor v_out;

    if (is_output_kv) {
        k_embed_out = at::empty({B, N, S, rope_size}, kv.options());
        v_out = at::empty({B, N, S, rms_size}, kv.options());
    } else {
        k_embed_out = at::empty({0}, kv.options());
        v_out = at::empty({0}, kv.options());
    }

    // All params as left values for EXEC_KERNEL_CMD
    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
    float epsVal = static_cast<float>(epsilon);
    int32_t isOutKv = is_output_kv ? 1 : 0;
    int32_t B_val = B;
    int32_t S_val = S;
    int32_t N_val = N;
    int32_t hidden_val = hidden_size;
    int32_t rms_val = rms_size;
    int32_t rope_val = rope_size;
    int32_t cache_mode_val = cache_mode_int;
    int32_t has_quant_k_val = has_quant_k;
    int32_t has_quant_v_val = has_quant_v;
    int32_t total_elems = total_elements;
    int32_t used_cores = usedCoreNum;
    int32_t tasks_per_core = tasksPerCore;
    int64_t dtype_flag = dtypeFlag;

    // Handle optional tensors - create empty tensors if not provided
    at::Tensor k_rope_scale_tensor = k_rope_scale.defined() ? k_rope_scale : at::empty({0}, at::kFloat);
    at::Tensor c_kv_scale_tensor = c_kv_scale.defined() ? c_kv_scale : at::empty({0}, at::kFloat);
    at::Tensor k_rope_offset_tensor = k_rope_offset.defined() ? k_rope_offset : at::empty({0}, at::kFloat);
    at::Tensor c_kv_offset_tensor = c_kv_offset.defined() ? c_kv_offset : at::empty({0}, at::kFloat);

    // Launch kernel with expanded tiling params
    EXEC_KERNEL_CMD(kv_rmsnorm_rope_cache, blockDim,
                    kv, gamma, cos, sin, index, k_cache, ckv_cache,
                    k_rope_scale_tensor, c_kv_scale_tensor,
                    k_rope_offset_tensor, c_kv_offset_tensor,
                    k_cache_out, ckv_cache_out, k_embed_out, v_out,
                    B_val, S_val, N_val, hidden_val, rms_val, rope_val,
                    cache_mode_val, isOutKv, has_quant_k_val, has_quant_v_val,
                    epsVal, total_elems, used_cores, tasks_per_core, dtype_flag);

    return {k_cache_out, ckv_cache_out, k_embed_out, v_out};
}

} // namespace ascend_kernel
