// KV RMSNorm RoPE Cache op_host — host-side implementation using torch_npu native API
// The AscendC kernel code is preserved in op_kernel/ for reference

#include <algorithm>
#include <cstdint>

#include <torch/extension.h>
#include <torch/library.h>

#include "torch_kernel_helper.h"

namespace ascend_kernel {

std::vector<at::Tensor> kv_rmsnorm_rope_cache(
    const at::Tensor &kv,
    const at::Tensor &gamma,
    const at::Tensor &cos,
    const at::Tensor &sin,
    const at::Tensor &index,
    const at::Tensor &k_cache,
    const at::Tensor &ckv_cache,
    const at::Tensor &k_rope_scale,
    const at::Tensor &c_kv_scale,
    const at::Tensor &k_rope_offset,
    const at::Tensor &c_kv_offset,
    double epsilon,
    const std::string &cache_mode,
    bool is_output_kv)
{
    // Input validation
    TORCH_CHECK(kv.dim() == 4, "kv must be 4D [B, N, S, hidden_size]");
    TORCH_CHECK(gamma.dim() == 1, "gamma must be 1D [rms_size]");
    TORCH_CHECK(cos.dim() == 4, "cos must be 4D [B, N, S, rope_size]");
    TORCH_CHECK(sin.dim() == 4, "sin must be 4D [B, N, S, rope_size]");
    TORCH_CHECK(kv.is_contiguous(), "kv must be contiguous");

    // Call torch_npu native implementation
    // Note: The custom AscendC kernel is preserved in kernel/op_kernel/ for reference,
    // but due to the extreme complexity of this operator (6 cache modes, multiple index
    // dimensions, quantization), we use the torch_npu native implementation here.
    at::Tensor k_rope_scale_t = k_rope_scale.defined() && k_rope_scale.numel() > 0 ? k_rope_scale : at::Tensor();
